-- Datos: traducciones al alemán (de) y español (es) de los cursos existentes.
-- Los cursos creados antes de 2026-09-27 tenían la columna "traducciones" vacía (NULL).
-- Cada UPDATE comprueba id Y nombre en inglés: si en esta BD el id no corresponde a ese curso,
-- no se toca nada (0 rows affected). Se puede ejecutar varias veces sin problema.

SET NAMES utf8mb4;

-- 1: CERAMICS CLASS (1st part HAND BUILDING + 2nd part GLAZING)
UPDATE curso SET traducciones = '{\"de\":{\"nombre\":\"KERAMIKKURS (1. Teil AUFBAUKERAMIK + 2. Teil GLASIEREN)\",\"subtitulo\":\"Lerne, Keramik aufzubauen und zu glasieren\",\"descripcion\":\"Mein Aufbaukeramik-Kurs ist für alle gedacht – ob du Anfänger*in oder schon erfahrene*r Keramiker*in bist. Ich begleite dich individuell und teile meine persönlichen Geheimnisse, abgestimmt auf das Niveau jeder Teilnehmerin und jedes Teilnehmers.\\n\\nIm Preis sind 2 Termine enthalten:\\n•\\t1. Teil – Aufbau deiner Keramik (ca. 2,5 Std.)\\n•\\t2. Teil – Glasieren deiner Keramik (ca. 2–2,5 Std.)\\n\\nIm ersten Teil zeige ich dir Aufbautechniken, mit denen du deine Keramik gestaltest – je nach Größe und Komplexität entstehen 1–3 Stücke. Etwa 2–3 Wochen später treffen wir uns zum zweiten Teil des Kurses wieder: In der 2-stündigen Einheit lernst du, deine Werke zu glasieren. Den zweiten Termin vereinbaren wir gemeinsam beim ersten Treffen.\\n\\nAm Ende des Kurses kennst du meine Glasurgeheimnisse und Tipps, um Keramik selbstständig herzustellen – sogar zu Hause. Du lernst, Keramik aufzubauen, ohne viel Geld für Material und Ausrüstung ausgeben zu müssen, und ich beantworte all deine Fragen zum Ablauf, zum Brennen, zum Ofen, zu Werkzeugen usw.\\n\\nZusätzliche kostenpflichtige Optionen (Aufpreise sind vor Ort in bar zu bezahlen):\\n•\\tEine Walskulptur, die als Lampe funktioniert – 20 € Aufpreis\\n•\\tEine große Ikebana-Vase – 20 € Aufpreis\\n•\\tEin zusätzliches kleines Stück (z. B. Suppenteller) – 10 € Aufpreis\",\"nivel\":\"Alle sind willkommen – von Menschen, die noch nie getöpfert haben, bis zu erfahrenen Keramiker*innen\",\"duracion\":\"2 Termine à 2–3 Std. (je nach Größe deines Projekts) – INSGESAMT 5 Std.\",\"piezas\":\"Gestalte entweder 1 großes Stück (Vase oder große Schale), 2 mittlere Stücke (Suppenschalen, Teller, Becher ohne Henkel) oder 3 kleine Stücke (Suppenteller oder kleine Schmuckschalen).\",\"materiales\":\"Inklusive: passender Ton für dein Projekt, Glasuren, zwei Brände sowie Zugang zu allen nötigen Werkzeugen, Geräten und Schürzen vor Ort.\"},\"es\":{\"nombre\":\"CLASE DE CERÁMICA (1.ª parte MODELADO A MANO + 2.ª parte ESMALTADO)\",\"subtitulo\":\"Aprende a modelar y esmaltar cerámica\",\"descripcion\":\"Mi clase de cerámica modelada a mano está pensada para todo el mundo, tanto si eres principiante como si ya tienes experiencia. Te acompaño de forma individual y comparto mis secretos personales adaptados al nivel de cada alumno.\\n\\nEl precio incluye 2 sesiones:\\n•\\t1.ª parte – Modelado a mano de tu cerámica (aprox. 2,5 h)\\n•\\t2.ª parte – Esmaltado de tu cerámica (aprox. 2–2,5 h)\\n\\nEn la primera parte te guío por las técnicas de modelado a mano para crear tu cerámica: podrás hacer de 1 a 3 piezas según su tamaño y complejidad. Unas 2–3 semanas después nos volvemos a ver para la segunda parte del curso, una sesión de 2 horas en la que aprenderás a esmaltar tus creaciones. La fecha de la segunda sesión la acordamos juntos durante la primera clase.\\n\\nAl terminar el curso conocerás mis secretos y trucos de esmaltado para crear cerámica por tu cuenta, incluso en casa. Aprenderás a hacer cerámica sin gastar mucho dinero en material y equipo, y responderé a todas tus preguntas sobre el proceso, la cocción, el horno, las herramientas, etc.\\n\\nHay opciones adicionales de pago (los suplementos se pagan en efectivo en el estudio):\\n•\\tCrear una escultura de ballena que funciona como lámpara – 20 € extra\\n•\\tCrear un jarrón grande de ikebana – 20 € extra\\n•\\tPieza pequeña adicional (p. ej., plato hondo) – 10 € extra\",\"nivel\":\"Cualquier nivel es bienvenido, desde quien nunca ha probado la cerámica hasta ceramistas avanzados\",\"duracion\":\"2 clases de 2–3 h cada una (según el tamaño de tu proyecto) – EN TOTAL 5 h\",\"piezas\":\"Crea 1 pieza grande (jarrón o cuenco grande), 2 piezas medianas (cuencos de sopa, platos, tazas sin asa) o 3 piezas pequeñas (platos hondos o bandejitas para joyas).\",\"materiales\":\"Incluye arcilla adecuada para el proyecto, esmaltes, dos cocciones y acceso a todas las herramientas, equipos y delantales necesarios en el estudio.\"}}' WHERE id = 1 AND nombre = 'CERAMICS CLASS (1st part HAND BUILDING + 2nd part GLAZING)';

-- 2: GLAZING CLASS (2nd part)
UPDATE curso SET traducciones = '{\"de\":{\"nombre\":\"GLASURKURS (2. Teil)\",\"subtitulo\":\"Lerne meine Glasurgeheimnisse\",\"descripcion\":\"Mein Glasurkurs ist für alle gedacht – ob du Anfänger*in oder schon erfahrene*r Keramiker*in bist. Ich begleite dich individuell und teile meine persönlichen Geheimnisse, abgestimmt auf das Niveau und die kreativen Ziele jeder Teilnehmerin und jedes Teilnehmers. In diesem praktischen Kurs entdeckst du die Techniken hinter meinen typischen Glasuren und lernst, deinen eigenen Keramikstücken leuchtendes Leben einzuhauchen. Ich gebe dir alle Informationen, die du brauchst, um selbst mit dem Glasieren loszulegen, und teile meine schönsten Glasurkombinationen. Vorkenntnisse sind nicht nötig – nur Freude an Kreativität und Lust, mit Glasuren zu experimentieren!\\n\\nBITTE BEACHTEN: Dieser Kurs ist nur für alle, die:\\n•\\tden „AUFBAUKERAMIK-KURS (1. Teil)“ gebucht haben und ihren Glasurkurs reservieren möchten,\\n•\\tein eigenes geschrühtes Stück haben und nur meinen Glasurkurs buchen möchten, um meine Geheimnisse zu lernen,\\n•\\tvon mir gefertigte Teller glasieren möchten (Aufpreis 10 €/Stück) – für diese Option kontaktiere mich bitte nach der Buchung\",\"nivel\":\"Alle sind willkommen – von Menschen, die noch nie getöpfert haben, bis zu erfahrenen Keramiker*innen\",\"duracion\":\"2–2,5 Std. (je nach Größe deines Stücks und Anzahl der Glasuren)\",\"piezas\":\"Glasiere dein eigenes geschrühtes Stück aus dem 1. Teil des Kurses oder eines meiner Stücke gegen Aufpreis (10 €/Stück) – für diese Option kontaktiere mich bitte nach der Buchung\",\"materiales\":\"Inklusive: passende Glasuren für dein Projekt, ein Brand bei 1220 °C sowie Zugang zu allen nötigen Werkzeugen, Geräten und Schürzen vor Ort.\"},\"es\":{\"nombre\":\"CLASE DE ESMALTADO (2.ª parte)\",\"subtitulo\":\"Aprende mis secretos de esmaltado\",\"descripcion\":\"Mi clase de esmaltado de cerámica está pensada para todo el mundo, tanto si eres principiante como si ya tienes experiencia. Te acompaño de forma individual y comparto mis secretos personales adaptados al nivel y a las ambiciones creativas de cada alumno. En esta clase práctica descubrirás las técnicas detrás de mis acabados de esmalte característicos y aprenderás a dar vida y color a tus propias piezas. Te doy toda la información que necesitas para empezar a esmaltar por tu cuenta y comparto mis combinaciones de esmaltes más espectaculares. No hace falta experiencia: ¡solo ganas de crear y de experimentar con esmaltes!\\n\\nTEN EN CUENTA: esta clase es solo para quienes:\\n•\\than reservado la «CLASE DE MODELADO A MANO (1.ª parte)» y quieren reservar su clase de esmaltado,\\n•\\ttienen su propia pieza bizcochada y quieren reservar solo mi clase de esmaltado para aprender mis secretos,\\n•\\tquieren esmaltar platos creados por mí con coste adicional (10 € extra por pieza); para esta opción, contáctame después de reservar\",\"nivel\":\"Cualquier nivel es bienvenido, desde quien nunca ha probado la cerámica hasta ceramistas avanzados\",\"duracion\":\"2–2,5 h (según el tamaño de tu pieza y el número de esmaltes)\",\"piezas\":\"Esmalta tu propia pieza bizcochada de la 1.ª parte del curso o una de mis piezas con coste adicional (10 € extra por pieza); para esta opción, contáctame después de reservar\",\"materiales\":\"Incluye esmaltes adecuados para el proyecto, una cocción a 1220 °C y acceso a todas las herramientas, equipos y delantales necesarios en el estudio.\"}}' WHERE id = 2 AND nombre = 'GLAZING CLASS (2nd part)';

-- 3: KINTSUGI CLASS
UPDATE curso SET traducciones = '{\"de\":{\"nombre\":\"KINTSUGI-KURS\",\"subtitulo\":\"Lerne, deine Keramik zu reparieren\",\"descripcion\":\"Kintsugi ist die japanische Kunst, zerbrochene Keramik zu reparieren, indem die Bruchstellen mit Gold verbunden werden. Als Philosophie versteht sie Bruch und Reparatur als Teil der Geschichte eines Gegenstands – nicht als etwas, das man verstecken muss. In meinem Atelier zeige ich dir eine vereinfachte Methode, mit der du ein Keramikstück reparieren kannst. Du kannst dein eigenes zerbrochenes Stück mitbringen oder eines in meinem Keramikatelier bekommen.\",\"nivel\":\"Keine Vorkenntnisse nötig\",\"duracion\":\"1 Termin, ca. 1,5–2 Std.\",\"piezas\":\"Bring deine zerbrochenen Keramikstücke mit. Im Workshop sind bis zu 2 Klebestellen möglich.\",\"materiales\":\"Inklusive: Goldpulver, passender Kleber sowie Zugang zu allen nötigen Werkzeugen, Geräten und Schürzen vor Ort.\"},\"es\":{\"nombre\":\"CLASE DE KINTSUGI\",\"subtitulo\":\"Aprende a reparar tu cerámica\",\"descripcion\":\"El kintsugi es el arte japonés de reparar la cerámica rota uniendo las zonas de rotura con oro. Como filosofía, entiende la rotura y la reparación como parte de la historia de un objeto, y no como algo que haya que ocultar. En mi estudio enseño un método simplificado con el que podrás reparar una pieza de cerámica. Puedes traer tu propia pieza rota o conseguir una en mi estudio de cerámica.\",\"nivel\":\"No se necesita experiencia previa\",\"duracion\":\"1 clase de aprox. 1,5–2 h\",\"piezas\":\"Trae tus piezas de cerámica rotas. En el taller se pueden hacer hasta 2 uniones.\",\"materiales\":\"Incluye polvo de oro, pegamento adecuado y acceso a todas las herramientas, equipos y delantales necesarios en el estudio.\"}}' WHERE id = 3 AND nombre = 'KINTSUGI CLASS';

-- 4: GLASS MEETS CERAMICS CLASS
UPDATE curso SET traducciones = '{\"de\":{\"nombre\":\"GLAS TRIFFT KERAMIK – KURS\",\"subtitulo\":\"Lerne zwei besondere Handwerke: Keramik und Glas\",\"descripcion\":\"Im Kurs GLAS TRIFFT KERAMIK entdeckst du die Verbindung zweier besonderer Handwerke: Keramik und Glas. Im Laufe des Workshops lernst du nicht nur Aufbautechniken der Keramik, sondern auch, wie du Glaselemente in deine Werke einbindest. Diese einzigartige Kombination eröffnet kreative Möglichkeiten: Du gestaltest und baust entweder eine eindrucksvolle Wandlampe oder einen eleganten Kerzenhalter.\\n\\nIm ersten Termin formst du deinen Keramikkörper mit traditionellen Aufbautechniken – Schritt für Schritt angeleitet und passend zu deinem Erfahrungsstand. Im zweiten Teil des Kurses, nachdem deine Keramik geschrüht wurde, lernst du, Glas einzuarbeiten: Du setzt Glasstücke sorgfältig in dein Werk ein, die beim letzten Brand verschmelzen. So entstehen außergewöhnliche, funktionale Kunstobjekte, die die Transparenz von Glas mit der Stärke und Textur von Keramik verbinden.\\n\\nOb du eine Wandlampe gestaltest, die zauberhafte Lichtmuster wirft, oder einen Kerzenhalter, der Wärme und Farbe in dein Zuhause bringt – du nimmst ein wirklich einzigartiges Stück mit nach Hause und das Wissen, um weitere Glas-Keramik-Projekte selbst umzusetzen.\",\"nivel\":\"Alle sind willkommen – von Menschen, die noch nie getöpfert haben, bis zu erfahrenen Keramiker*innen\",\"duracion\":\"2 Termine à 4–6 Std. (je nach Größe deines Projekts) – INSGESAMT 10 Std.\",\"piezas\":\"Gestalte eine Wandlampe, die zauberhafte Lichtmuster wirft, oder einen Kerzenhalter, der Wärme und Farbe in dein Zuhause bringt.\",\"materiales\":\"Inklusive: passender Ton und passendes Glas für dein Projekt sowie Zugang zu allen nötigen Werkzeugen, Geräten und Schürzen vor Ort.\"},\"es\":{\"nombre\":\"CLASE CRISTAL Y CERÁMICA\",\"subtitulo\":\"Aprende dos oficios extraordinarios: la cerámica y el vidrio\",\"descripcion\":\"En la CLASE CRISTAL Y CERÁMICA te invito a explorar la fusión de dos oficios extraordinarios: la cerámica y el vidrio. A lo largo del taller no solo dominarás las técnicas de modelado a mano, sino que también descubrirás cómo incorporar elementos de vidrio a tus creaciones. Esta combinación única abre muchas posibilidades creativas y te permite diseñar y construir una llamativa lámpara de pared o un elegante portavelas.\\n\\nEn la primera sesión darás forma a tu base de cerámica con técnicas tradicionales de modelado a mano, guiado paso a paso según tu nivel. En la segunda parte del curso, una vez bizcochada tu cerámica, aprenderás a integrar el vidrio: colocarás con cuidado las piezas de vidrio en tu obra, que se fundirán en la cocción final. El resultado son piezas de arte funcionales y excepcionales que combinan la translucidez del vidrio con la fuerza y la textura de la cerámica.\\n\\nTanto si eliges una lámpara de pared que proyecta preciosos juegos de luz como un portavelas que aporta calidez y color a tu hogar, te llevarás un objeto verdaderamente único y los conocimientos para seguir creando proyectos de vidrio y cerámica por tu cuenta.\",\"nivel\":\"Cualquier nivel es bienvenido, desde quien nunca ha probado la cerámica hasta ceramistas avanzados\",\"duracion\":\"2 clases de 4–6 h cada una (según el tamaño de tu proyecto) – EN TOTAL 10 h\",\"piezas\":\"Crea una lámpara de pared que proyecta preciosos juegos de luz o un portavelas que aporta calidez y color a tu hogar.\",\"materiales\":\"Incluye arcilla y vidrio adecuados para el proyecto y acceso a todas las herramientas, equipos y delantales necesarios en el estudio.\"}}' WHERE id = 4 AND nombre = 'GLASS MEETS CERAMICS CLASS';

-- 5: HAND-BUILDING CLASS (1st part)
UPDATE curso SET traducciones = '{\"de\":{\"nombre\":\"AUFBAUKERAMIK-KURS (1. Teil)\",\"subtitulo\":\"Entdecke Profi-Techniken der Aufbaukeramik.\",\"descripcion\":\"Mein Aufbaukeramik-Kurs ist für alle gedacht – ob du Anfänger*in oder schon erfahrene*r Keramiker*in bist. Ich begleite dich individuell und teile meine persönlichen Geheimnisse, abgestimmt auf das Niveau und die kreativen Ziele jeder Teilnehmerin und jedes Teilnehmers.\\n\\nAm Ende des Kurses kennst du meine Geheimnisse und Tipps der Aufbaukeramik, um Keramik selbstständig herzustellen – sogar zu Hause. Du lernst, Keramik aufzubauen, ohne viel Geld für Material und Ausrüstung ausgeben zu müssen, und ich beantworte all deine Fragen zum Ablauf, zum Brennen, zum Ofen, zu Werkzeugen usw.\\n\\nZum Glasieren deiner Keramik hast du zwei Möglichkeiten:\\n•\\tDu lässt deine Keramik weiß glasieren, oder\\n•\\tdu nimmst nach mindestens 2–3 Wochen am zweiten Teil meines Kurses teil und lernst meine Glasurgeheimnisse\",\"nivel\":\"Alle sind willkommen – von Menschen, die noch nie getöpfert haben, bis zu erfahrenen Keramiker*innen\",\"duracion\":\"Ein Termin (ca. 2,5–3 Std.), ausschließlich zu Aufbautechniken.\",\"piezas\":\"Gestalte entweder 1 großes Stück (Vase oder große Schale), 2 mittlere Stücke (Suppenschalen, Teller, Becher ohne Henkel) oder 3 kleine Stücke (Suppenteller oder kleine Schmuckschalen).\",\"materiales\":\"Ton, Werkzeuge, Geräte und Schürzen sind inklusive, ebenso der erste Brand deiner Werke und eine weiße Glasur (farbiges Glasieren ist möglich, wenn du den zweiten Teil meines Kurses buchst).\"},\"es\":{\"nombre\":\"CLASE DE MODELADO A MANO (1.ª parte)\",\"subtitulo\":\"Descubre técnicas expertas de modelado a mano en cerámica.\",\"descripcion\":\"Mi clase de cerámica modelada a mano está pensada para todo el mundo, tanto si eres principiante como si ya tienes experiencia. Te acompaño de forma individual y comparto mis secretos personales adaptados al nivel y a las ambiciones creativas de cada alumno.\\n\\nAl terminar el curso conocerás mis secretos y trucos de modelado a mano para crear cerámica por tu cuenta, incluso en casa. Aprenderás a hacer cerámica sin gastar mucho dinero en material y equipo, y responderé a todas tus preguntas sobre el proceso, la cocción, el horno, las herramientas, etc.\\n\\nPara esmaltar tu cerámica tienes dos opciones:\\n•\\tPuedes elegir que tu cerámica se esmalte con un acabado blanco, o\\n•\\tPuedes apuntarte a la segunda parte de mi curso pasadas al menos 2–3 semanas y aprender mis secretos de esmaltado\",\"nivel\":\"Cualquier nivel es bienvenido, desde quien nunca ha probado la cerámica hasta ceramistas avanzados\",\"duracion\":\"Una sesión (aprox. 2,5–3 horas) dedicada exclusivamente a las técnicas de modelado a mano.\",\"piezas\":\"Crea 1 pieza grande (jarrón o cuenco grande), 2 piezas medianas (cuencos de sopa, platos, tazas sin asa) o 3 piezas pequeñas (platos hondos o bandejitas para joyas).\",\"materiales\":\"Incluye toda la arcilla, herramientas, equipos y delantales, además de la primera cocción de tus creaciones y el esmaltado en blanco (el esmaltado en color es posible si reservas la segunda parte de mi clase).\"}}' WHERE id = 5 AND nombre = 'HAND-BUILDING CLASS (1st part)';

